def rule_long_term_debt_year_end(doc: dict) -> list[dict]:
    try:
        lines = doc.get("lines") or []
        ordered = sorted(
            lines,
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("line_no", 10**9),
            ),
        )

        row_pat = re.compile(
            r"(?i)^\s*(?:total\s+)?long[- ]term debt"
            r"(?:"
            r"(?:\s+and\s+obligations\s+under\s+(?:capital|finance)\s+leases)"
            r"|(?:\s+obligations(?:\s+under\s+(?:capital|finance)\s+leases)?)"
            r"|(?:,\s*(?:net|net of current portion|less current portion|less:\s*current portion|excluding current portion))"
            r")?"
            r"(?:\s*\(\d+\))?\s*$"
        )
        bad_pat = re.compile(
            r"(?i)\b(?:including current portion|current portion of long[- ]term debt|"
            r"short[- ]term debt and current portion of long[- ]term debt|"
            r"due within one year|contractual obligations|future maturities|"
            r"consisted of the following|fair value|estimated fair value|"
            r"proceeds from long[- ]term debt|repayments of long[- ]term debt|"
            r"cash paid for interest|rights of holders|table of contents|"
            r"note\s+\d+\.?\s+long[- ]term debt)\b"
        )

        def clean(text: str) -> str:
            text = (text or "").replace("\u00a0", " ")
            return " ".join(text.split())

        def extract_amount(text: str):
            t = clean(text)
            if not t:
                return None
            if t in {"$", "€", "£"}:
                return None
            if re.fullmatch(r"[()\-–—]+", t):
                return "0"
            m = re.fullmatch(r"(?i)(?:[$€£]\s*)?(\d[\d,]*(?:\.\d+)?)", t)
            if m:
                return m.group(1)
            m = re.search(r"(?i)(\d[\d,]*(?:\.\d+)?)", t)
            if m and len(t) <= 20:
                return m.group(1)
            return None

        def add_span(text: str, source: dict) -> list[dict]:
            span = {"text": text}
            if source.get("page_no") is not None:
                span["page_no"] = source.get("page_no")
            if source.get("line_no") is not None:
                span["line_no"] = source.get("line_no")
            return [span]

        for i, item in enumerate(ordered):
            raw = clean(item.get("text"))
            if not raw:
                continue
            if not row_pat.match(raw):
                continue
            if bad_pat.search(raw):
                continue

            inline_amount = extract_amount(raw)
            if inline_amount is not None and inline_amount != raw:
                return add_span(inline_amount, item)

            currency_seen = False
            for j in range(i + 1, min(i + 5, len(ordered))):
                nxt = clean(ordered[j].get("text"))
                if not nxt:
                    continue
                if nxt in {"$", "€", "£"}:
                    currency_seen = True
                    continue
                amt = extract_amount(nxt)
                if amt is not None:
                    return add_span(amt, ordered[j])
                # Stop if the next nonblank line looks like prose rather than a number.
                if any(ch.isalpha() for ch in nxt):
                    break
                if currency_seen and re.fullmatch(r"[()\-–—]+", nxt):
                    return add_span("0", ordered[j])

        return [{"text": "0"}]
    except Exception:
        return []

import re


def rule_long_term_debt_line_window(doc: dict) -> list[dict]:
    try:
        out = []
        seen = set()
        kw_re = re.compile(
            r"("
            r"long[- ]term debt and obligations under finance leases|"
            r"long[- ]term debt and finance lease obligations|"
            r"long[- ]term debt and obligations|"
            r"long[- ]term debt obligations|"
            r"long[- ]term debt due within one year|"
            r"current portion of (?:debt|long[- ]term debt)(?: and obligations under finance leases)?|"
            r"debt and obligations under finance leases|"
            r"carrying value of long[- ]term debt|"
            r"long[- ]term obligations|"
            r"long[- ]term debt|"
            r"total debt outstanding|"
            r"debt and borrowings"
            r")",
            re.IGNORECASE,
        )
        row_start_re = re.compile(
            r"^\s*(?:"
            r"long[- ]term debt(?:\b|,|$| and obligations under finance leases| and finance lease obligations|"
            r" and obligations| obligations| due within one year|, including amounts due within one year)|"
            r"current portion of (?:debt|long[- ]term debt)(?: and obligations under finance leases)?|"
            r"debt and obligations under finance leases|"
            r"carrying value of long[- ]term debt|"
            r"long[- ]term obligations|"
            r"total debt outstanding"
            r")",
            re.IGNORECASE,
        )
        short_row_re = re.compile(r"^\s*(?:\$|[()\d,.\-]+|\s)+\s*$")
        date_header_re = re.compile(
            r"(?:\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b|\b20\d{2}\b|\b19\d{2}\b|"
            r"december\s+31,|june\s+30,|april\s+30,|january\s+31,|may\s+31,|march\s+31,|"
            r"september\s+30,|august\s+31,|february\s+28,|february\s+29,|year ended)",
            re.IGNORECASE,
        )
        continuation_re = re.compile(
            r"^(?:within one year|due within one year|current portion(?: of(?: long[- ]term)? debt)?|"
            r"thereafter|less: current portion.*|total|balances as of .+)$",
            re.IGNORECASE,
        )

        def alpha_word_count(text: str) -> int:
            return len(re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", text))

        def is_row_like(text: str) -> bool:
            low = text.lower().strip()
            if not low:
                return False
            if row_start_re.search(low):
                return alpha_word_count(low) <= 12
            return False

        def is_context_line(text: str) -> bool:
            low = text.lower().strip()
            if not low:
                return False
            if short_row_re.match(low):
                return True
            if re.fullmatch(r"[\d,().$\-\s]+", low):
                return True
            if date_header_re.search(low):
                return alpha_word_count(low) <= 12
            if continuation_re.match(low):
                return True
            return False

        by_page = {}
        for line in doc.get("lines") or []:
            by_page.setdefault(line.get("page_no"), []).append(line)

        for page_no, page_lines in by_page.items():
            for idx, line in enumerate(page_lines):
                text = str(line.get("text") or "").strip()
                if not text or not is_row_like(text):
                    continue

                start = max(0, idx - 12)
                end = min(len(page_lines), idx + 4)
                snippet_lines = []
                for item in page_lines[start:end]:
                    item_text = str(item.get("text") or "").strip()
                    if item_text and is_context_line(item_text):
                        snippet_lines.append(item_text)

                snippet = "\n".join(snippet_lines).strip()
                if not snippet:
                    continue

                key = (page_no, line.get("line_no"), snippet)
                if key in seen:
                    continue
                seen.add(key)
                out.append(
                    {
                        "page_no": page_no,
                        "line_no": line.get("line_no"),
                        "text": snippet,
                    }
                )

        return out
    except Exception:
        return []

def rule_debt_zero_for_8k_forms(doc: dict) -> list[dict]:
    """Match 8-K documents where the answer should often be 0 because no financial debt table exists."""
    out = []
    try:
        has_8k = False
        has_debt_table = False
        for span in doc.get("texts", []):
            txt = (span.get("text") or "").lower()
            if "form 8-k" in txt:
                has_8k = True
            if span.get("label") == "table" and ("balance sheet" in txt or "long-term debt" in txt or "debt" in txt):
                has_debt_table = True
        if has_8k and not has_debt_table:
            for span in doc.get("texts", []):
                if "form 8-k" in (span.get("text") or "").lower():
                    out.append(span)
    except Exception:
        return []
    return out

